/**
 * Conexión automática de escenas. **Experimental.**
 *
 * El plan es explícito con esta función: es un algoritmo no trivial, no se
 * puede declarar terminado si no alcanza calidad, y lo que produzca necesita
 * revisión humana antes de publicarse. Este módulo está escrito sobre esa
 * base, y por eso tiene tres rasgos que no son habituales:
 *
 *  1. No crea marcadores. Devuelve **propuestas**, que quien llama convierte
 *     en marcadores con `autoGenerated: true` y `reviewed: false`. El plan de
 *     publicación no los publica hasta que una persona los confirma.
 *  2. Cada propuesta lleva confianza y el motivo por el que se emitió. Una
 *     confianza sin explicación no se puede evaluar: el autor necesita saber
 *     si viene de coordenadas GPS o de un parecido de histograma.
 *  3. Las señales que usa son las que el proyecto tiene de verdad: posición
 *     GPS, rumbo de captura, marca de tiempo y posición en el plano. **No**
 *     hay emparejamiento de puntos característicos entre imágenes, porque eso
 *     exige procesamiento de imagen que esta capa no hace, y fingirlo con un
 *     parecido de color produciría propuestas plausibles y equivocadas, que
 *     son las peores.
 *
 * Lo que este módulo hace bien: si las panorámicas traen GPS —lo habitual en
 * una cámara 360 moderna— propone conexiones entre las más cercanas, con la
 * orientación correcta calculada por el rumbo geográfico. Si no traen GPS pero
 * están colocadas en un plano, usa el plano. Si no hay ni una cosa ni otra,
 * cae a la secuencia temporal de captura, que es una señal débil y se declara
 * como tal.
 */
import {
  degToRad,
  radToDeg,
  wrapYaw,
  type Media,
  type Plan,
  type PlanMarker,
  type Scene,
  type Uuid,
} from '@it360/domain';

/** Señal en la que se basa una propuesta, de más fiable a menos. */
export type ConnectionEvidence = 'gps' | 'plan' | 'captureOrder';

export const EVIDENCE_LABELS: Readonly<Record<ConnectionEvidence, string>> = {
  gps: 'Posición GPS de la captura',
  plan: 'Posición en el plano',
  captureOrder: 'Orden de captura (señal débil)',
};

/**
 * Confianza máxima por tipo de señal.
 *
 * Son techos, no valores fijos: la confianza final baja con la distancia y con
 * la falta de rumbo. El techo del orden de captura es bajo a propósito —0,35—
 * porque dos fotos consecutivas en el tiempo pueden estar en extremos opuestos
 * de la planta, y presentar eso con confianza alta llevaría al autor a aceptar
 * propuestas sin mirarlas, que es exactamente lo que la revisión debe evitar.
 */
const EVIDENCE_CEILING: Readonly<Record<ConnectionEvidence, number>> = {
  gps: 0.9,
  plan: 0.75,
  captureOrder: 0.35,
};

export interface ConnectionProposal {
  readonly fromSceneId: Uuid;
  readonly toSceneId: Uuid;
  /** Azimut sugerido para el marcador en la escena de origen, en radianes. */
  readonly yaw: number;
  /** Elevación sugerida: siempre el horizonte, salvo desnivel conocido. */
  readonly pitch: number;
  /** Distancia estimada entre los dos puntos de captura, en metros. */
  readonly distanceM: number | null;
  readonly evidence: ConnectionEvidence;
  /** De 0 a 1. Nunca 1: ninguna de estas señales es una certeza. */
  readonly confidence: number;
  /** Explicación para que el autor pueda juzgar la propuesta. */
  readonly reason: string;
}

export interface AutoConnectOptions {
  /** Distancia máxima para proponer una conexión, en metros. */
  readonly maxDistanceM?: number;
  /** Número máximo de propuestas por escena. */
  readonly maxPerScene?: number;
  /** Confianza mínima para emitir la propuesta. */
  readonly minConfidence?: number;
}

export interface AutoConnectResult {
  readonly proposals: readonly ConnectionProposal[];
  /** Escenas para las que no se pudo proponer nada, con el motivo. */
  readonly skipped: ReadonlyArray<{ sceneId: Uuid; reason: string }>;
  /** Señal que se pudo usar; `null` si ninguna. */
  readonly evidence: ConnectionEvidence | null;
  /**
   * Por qué la lista salió vacía, cuando salió vacía.
   *
   * Distinguirlo importa: «el GPS dice que estas escenas están lejos» y «no
   * hay datos de posición» llevan a acciones distintas —en el primer caso el
   * autor sabe que no son contiguas, en el segundo que falta información—, y
   * un mensaje único para los dos casos haría que el autor buscase el problema
   * donde no está.
   */
  readonly emptyReason: 'tooFar' | 'lowConfidence' | 'noEvidence' | null;
}

const EARTH_RADIUS_M = 6_371_000;

/**
 * Distancia entre dos coordenadas geográficas, en metros.
 *
 * Fórmula del semiverseno. A escala de planta —decenas o cientos de metros—
 * cualquier aproximación plana valdría, pero la del semiverseno no se rompe si
 * alguien instala la cámara en dos sitios separados por un kilómetro.
 */
function haversineM(
  a: { readonly latitude: number; readonly longitude: number },
  b: { readonly latitude: number; readonly longitude: number },
): number {
  const dLat = degToRad(b.latitude - a.latitude);
  const dLon = degToRad(b.longitude - a.longitude);
  const lat1 = degToRad(a.latitude);
  const lat2 = degToRad(b.latitude);

  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
  return 2 * EARTH_RADIUS_M * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** Rumbo inicial de A a B, en radianes desde el norte geográfico. */
function bearingRad(
  a: { readonly latitude: number; readonly longitude: number },
  b: { readonly latitude: number; readonly longitude: number },
): number {
  const lat1 = degToRad(a.latitude);
  const lat2 = degToRad(b.latitude);
  const dLon = degToRad(b.longitude - a.longitude);

  const y = Math.sin(dLon) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLon);
  return Math.atan2(y, x);
}

interface ScenePoint {
  readonly sceneId: Uuid;
  readonly latitude: number;
  readonly longitude: number;
  /** Rumbo al que apuntaba el centro de la panorámica, si se conoce. */
  readonly headingRad: number | null;
  readonly capturedAt: string | null;
}

/** Extrae las posiciones de captura disponibles. */
function gpsPoints(scenes: readonly Scene[], media: readonly Media[]): readonly ScenePoint[] {
  const byId = new Map(media.map((m) => [m.id, m]));
  const points: ScenePoint[] = [];

  for (const scene of scenes) {
    if (scene.mediaId === null) continue;
    const asset = byId.get(scene.mediaId);
    const gps = asset?.panorama?.gps;
    if (asset === undefined || gps === null || gps === undefined) continue;

    points.push({
      sceneId: scene.id,
      latitude: gps.latitude,
      longitude: gps.longitude,
      headingRad: asset.panorama?.capturedHeadingRad ?? null,
      capturedAt: asset.createdAt,
    });
  }

  return points;
}

/**
 * Propone conexiones a partir del GPS de las capturas.
 *
 * El azimut del marcador se calcula restando al rumbo geográfico el rumbo al
 * que apuntaba el centro de la panorámica. Sin ese rumbo no se puede situar el
 * marcador: la propuesta se emite igualmente, con el azimut sin corregir y
 * confianza reducida, y el motivo lo dice. Es la diferencia entre «el marcador
 * está donde debe» y «hay un camino hacia allí, colóquelo usted».
 */
function proposeFromGps(
  points: readonly ScenePoint[],
  options: Required<AutoConnectOptions>,
): readonly ConnectionProposal[] {
  const proposals: ConnectionProposal[] = [];

  for (const from of points) {
    const candidates = points
      .filter((to) => to.sceneId !== from.sceneId)
      .map((to) => ({ to, distance: haversineM(from, to) }))
      .filter(({ distance }) => distance <= options.maxDistanceM)
      .sort((a, b) => a.distance - b.distance)
      .slice(0, options.maxPerScene);

    for (const { to, distance } of candidates) {
      const geographic = bearingRad(from, to);
      const hasHeading = from.headingRad !== null;
      const yaw = wrapYaw(geographic - (from.headingRad ?? 0));

      // La confianza decae con la distancia: dos capturas a dos metros son
      // casi con seguridad contiguas; a cincuenta, puede haber una pared en
      // medio y el algoritmo no la ve.
      const proximity = 1 - Math.min(distance / options.maxDistanceM, 1);
      const confidence = Math.min(
        EVIDENCE_CEILING.gps,
        (hasHeading ? 0.55 : 0.3) + proximity * 0.35,
      );

      if (confidence < options.minConfidence) continue;

      proposals.push({
        fromSceneId: from.sceneId,
        toSceneId: to.sceneId,
        yaw,
        pitch: 0,
        distanceM: Math.round(distance * 10) / 10,
        evidence: 'gps',
        confidence: Math.round(confidence * 100) / 100,
        reason: hasHeading
          ? `A ${distance.toFixed(1)} m, rumbo ${Math.round(radToDeg(geographic))}° geográficos, corregido por el rumbo de captura.`
          : `A ${distance.toFixed(1)} m. La captura no registró su rumbo, así que el azimut del marcador es una estimación y hay que comprobarlo.`,
      });
    }
  }

  return proposals;
}

/**
 * Propone conexiones a partir de las posiciones en el plano.
 *
 * El plano da posiciones relativas en una imagen, no metros. Si el plano
 * declara su escala se estima la distancia; si no, se proponen las conexiones
 * sin distancia y con menos confianza. Inventar una escala para poder dar un
 * número en metros sería peor que no darlo.
 */
function proposeFromPlan(
  scenes: readonly Scene[],
  plan: Plan,
  markers: readonly PlanMarker[],
  options: Required<AutoConnectOptions>,
): readonly ConnectionProposal[] {
  const sceneIds = new Set(scenes.map((s) => s.id as string));
  const placed = markers.filter((m) => m.planId === plan.id && sceneIds.has(m.sceneId));
  const proposals: ConnectionProposal[] = [];

  /**
   * El plano no declara escala.
   *
   * El formato del proyecto guarda la orientación del plano pero no su escala,
   * así que las distancias en el plano son relativas y no hay metros que dar.
   * Se deja explícito en lugar de estimar una escala a partir del tamaño de la
   * imagen: un número en metros que viene de una suposición es peor que no
   * tener el número, porque el autor lo usaría para decidir.
   */
  const metersPerUnit: number | null = null;

  for (const from of placed) {
    const candidates = placed
      .filter((to) => to.sceneId !== from.sceneId)
      .map((to) => ({
        to,
        // Distancia en unidades normalizadas del plano (0 a 1 en cada eje).
        distance: Math.hypot(to.position.x - from.position.x, to.position.y - from.position.y),
      }))
      .sort((a, b) => a.distance - b.distance)
      .slice(0, options.maxPerScene);

    for (const { to, distance } of candidates) {
      const meters = metersPerUnit === null ? null : distance * metersPerUnit;
      if (meters !== null && meters > options.maxDistanceM) continue;

      // El eje Y de la imagen crece hacia abajo; el azimut se mide desde el
      // norte del plano. Sin esta inversión, el marcador apunta al lado
      // contrario en vertical y el error pasa inadvertido en planos simétricos.
      const dx = to.position.x - from.position.x;
      const dy = -(to.position.y - from.position.y);
      const onPlan = Math.atan2(dx, dy);
      const yaw = wrapYaw(onPlan + plan.orientation.northRad - plan.orientation.sceneNorthOffsetRad);

      const proximity = 1 - Math.min(distance / 0.5, 1);
      const confidence = Math.min(
        EVIDENCE_CEILING.plan,
        (metersPerUnit === null ? 0.35 : 0.5) + proximity * 0.25,
      );
      if (confidence < options.minConfidence) continue;

      proposals.push({
        fromSceneId: from.sceneId,
        toSceneId: to.sceneId,
        yaw,
        pitch: 0,
        distanceM: meters === null ? null : Math.round(meters * 10) / 10,
        evidence: 'plan',
        confidence: Math.round(confidence * 100) / 100,
        reason:
          meters === null
            ? 'Según su posición en el plano. El plano no declara escala, así que no hay distancia estimada.'
            : `A unos ${meters.toFixed(1)} m según la escala declarada del plano.`,
      });
    }
  }

  return proposals;
}

/**
 * Propone conexiones por orden de captura.
 *
 * Es la señal más débil y sólo se usa cuando no hay nada mejor. El azimut es
 * una convención —al frente— porque el orden temporal no dice nada sobre
 * dirección. La propuesta sirve para no dejar al autor con cuarenta escenas
 * desconectadas, no para acertar.
 */
function proposeFromCaptureOrder(
  scenes: readonly Scene[],
  media: readonly Media[],
  options: Required<AutoConnectOptions>,
): readonly ConnectionProposal[] {
  const byId = new Map(media.map((m) => [m.id, m]));
  const ordered = [...scenes]
    .filter((scene) => scene.mediaId !== null && byId.has(scene.mediaId))
    .sort((a, b) => {
      const ta = byId.get(a.mediaId as Uuid)?.createdAt ?? '';
      const tb = byId.get(b.mediaId as Uuid)?.createdAt ?? '';
      return ta.localeCompare(tb);
    });

  const confidence = EVIDENCE_CEILING.captureOrder;
  if (confidence < options.minConfidence) return [];

  const proposals: ConnectionProposal[] = [];
  for (let i = 0; i < ordered.length - 1; i += 1) {
    const from = ordered[i];
    const to = ordered[i + 1];
    if (from === undefined || to === undefined) continue;

    proposals.push({
      fromSceneId: from.id,
      toSceneId: to.id,
      yaw: 0,
      pitch: 0,
      distanceM: null,
      evidence: 'captureOrder',
      confidence,
      reason:
        'Capturas consecutivas en el tiempo. No hay información de posición, así que la dirección del marcador es una convención y hay que colocarlo a mano.',
    });
  }

  return proposals;
}

/**
 * Propone conexiones entre escenas con la mejor señal disponible.
 *
 * No mezcla señales: usa la mejor que encuentre para todo el conjunto. Mezclar
 * produciría un mapa de confianzas incomparables entre sí, y el autor no
 * podría ordenar las propuestas por fiabilidad, que es lo único que hace
 * manejable revisar cuarenta.
 */
export function proposeConnections(input: {
  readonly scenes: readonly Scene[];
  readonly media: readonly Media[];
  readonly plans?: readonly Plan[];
  readonly planMarkers?: readonly PlanMarker[];
  readonly options?: AutoConnectOptions;
}): AutoConnectResult {
  const options: Required<AutoConnectOptions> = {
    maxDistanceM: input.options?.maxDistanceM ?? 40,
    maxPerScene: input.options?.maxPerScene ?? 3,
    minConfidence: input.options?.minConfidence ?? 0.3,
  };

  const skipped: Array<{ sceneId: Uuid; reason: string }> = [];
  for (const scene of input.scenes) {
    if (scene.mediaId === null) {
      skipped.push({ sceneId: scene.id, reason: 'La escena no tiene imagen asignada.' });
    }
  }

  const gps = gpsPoints(input.scenes, input.media);
  if (gps.length >= 2) {
    const proposals = dedupe(proposeFromGps(gps, options));
    /**
     * Con GPS disponible no se cae a una señal peor.
     *
     * Si las coordenadas dicen que las escenas están a kilómetros, proponer
     * conexiones por orden de captura sería contradecir el dato bueno con el
     * malo. Se devuelve la lista vacía y el motivo.
     */
    const nearest = minimumSeparationM(gps);
    return {
      proposals,
      skipped,
      evidence: 'gps',
      emptyReason:
        proposals.length > 0
          ? null
          : nearest !== null && nearest > options.maxDistanceM
            ? 'tooFar'
            : 'lowConfidence',
    };
  }

  const plan = input.plans?.[0];
  const markers = input.planMarkers ?? [];
  if (plan !== undefined && markers.filter((m) => m.planId === plan.id).length >= 2) {
    const proposals = dedupe(proposeFromPlan(input.scenes, plan, markers, options));
    return {
      proposals,
      skipped,
      evidence: 'plan',
      emptyReason: proposals.length > 0 ? null : 'lowConfidence',
    };
  }

  const byOrder = proposeFromCaptureOrder(input.scenes, input.media, options);
  if (byOrder.length > 0) {
    return { proposals: dedupe(byOrder), skipped, evidence: 'captureOrder', emptyReason: null };
  }

  return {
    proposals: [],
    skipped: [
      ...skipped,
      ...(input.scenes.length < 2
        ? [{ sceneId: input.scenes[0]?.id ?? ('' as Uuid), reason: 'Hace falta más de una escena.' }]
        : []),
    ],
    evidence: null,
    emptyReason: 'noEvidence',
  };
}

/** Separación más pequeña entre dos capturas con GPS, en metros. */
function minimumSeparationM(points: readonly ScenePoint[]): number | null {
  let best: number | null = null;
  for (let i = 0; i < points.length; i += 1) {
    for (let j = i + 1; j < points.length; j += 1) {
      const a = points[i];
      const b = points[j];
      if (a === undefined || b === undefined) continue;
      const distance = haversineM(a, b);
      if (best === null || distance < best) best = distance;
    }
  }
  return best;
}

/**
 * Elimina propuestas duplicadas en el mismo sentido.
 *
 * Las conexiones recíprocas se conservan a propósito: un recorrido necesita el
 * marcador de ida en la escena A y el de vuelta en la B, y son dos marcadores
 * distintos con azimutes distintos.
 */
function dedupe(proposals: readonly ConnectionProposal[]): readonly ConnectionProposal[] {
  const seen = new Set<string>();
  const result: ConnectionProposal[] = [];

  for (const proposal of [...proposals].sort((a, b) => b.confidence - a.confidence)) {
    const key = `${proposal.fromSceneId}→${proposal.toSceneId}`;
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(proposal);
  }

  return result;
}

/**
 * Resumen para la interfaz antes de aplicar nada.
 *
 * El autor decide si merece la pena revisar las propuestas, y para eso
 * necesita saber cuántas son, de dónde salen y qué confianza tienen. Aplicar
 * primero y explicar después convierte la revisión en limpieza.
 */
export function summarizeProposals(result: AutoConnectResult): string {
  if (result.proposals.length === 0) {
    switch (result.emptyReason) {
      case 'tooFar':
        return 'Las capturas tienen GPS y están más separadas que la distancia máxima: según sus coordenadas, estas escenas no son contiguas. Amplíe la distancia máxima si sabe que sí lo son.';
      case 'lowConfidence':
        return 'No se encontró ninguna conexión que supere la confianza mínima.';
      default:
        return 'No hay información suficiente para proponer conexiones: las capturas no traen GPS, no están colocadas en un plano y no hay orden de captura utilizable.';
    }
  }

  const best = Math.max(...result.proposals.map((p) => p.confidence));
  const worst = Math.min(...result.proposals.map((p) => p.confidence));

  return [
    `${result.proposals.length} propuesta(s) a partir de: ${EVIDENCE_LABELS[result.evidence ?? 'captureOrder']}.`,
    `Confianza entre ${(worst * 100).toFixed(0)} % y ${(best * 100).toFixed(0)} %.`,
    'Todas entran marcadas como propuestas sin revisar y no se publicarán hasta que las confirme.',
  ].join(' ');
}
